function(container, apiUrl, tables) {
    // 業務ロジックモジュールのインポート（グローバルスコープから取得）
    const {
        collectSalesData,
        classifySalesDataByProduct,
        classifySalesDataByStore,
        filterValidProductData,
        collectWeatherData,
        collectEventData,
        collectSeasonalData,
        analyzeCorrelationSalesWeather,
        analyzeCorrelationSalesEvent,
        analyzeCorrelationSalesSeason,
        compareWithHistoricalData,
        findAlternativeComparisonData,
        validateComparisonPeriod
    } = window.aiLogic || {};

    // 売上データ収集ボタン
    const collectSalesBtn = container.querySelector('#collectSalesBtn');
    if (collectSalesBtn) {
        collectSalesBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで処理
                const salesData = collectSalesData ? collectSalesData(salesResponse.data, startDate, endDate) : salesResponse.data;

                const tbody = container.querySelector('#salesDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    salesData.forEach(item => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = item.date || item.salesDate;
                        row.insertCell(1).textContent = item.productId;
                        row.insertCell(2).textContent = item.quantity;
                        row.insertCell(3).textContent = item.amount;
                    });
                }
                window.aivicNotify.success('売上データを収集しました');
            } catch (error) {
                window.aivicNotify.error('売上データの収集に失敗しました: ' + error.message);
            }
        });
    }

    // 商品別分析ボタン
    const analyzeByProductBtn = container.querySelector('#analyzeByProductBtn');
    if (analyzeByProductBtn) {
        analyzeByProductBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで商品別分析
                const productAnalysis = classifySalesDataByProduct ? 
                    classifySalesDataByProduct(salesResponse.data) : 
                    salesResponse.data;

                const tbody = container.querySelector('#productAnalysisTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(productAnalysis).forEach(([productId, data]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = productId;
                        row.insertCell(1).textContent = data.totalQuantity || data.quantity || 0;
                        row.insertCell(2).textContent = data.totalAmount || data.amount || 0;
                        row.insertCell(3).textContent = data.averagePrice || (data.totalAmount / data.totalQuantity).toFixed(2) || 0;
                    });
                }
                window.aivicNotify.success('商品別分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('商品別分析に失敗しました: ' + error.message);
            }
        });
    }

    // 店舗別分析ボタン
    const analyzeByStoreBtn = container.querySelector('#analyzeByStoreBtn');
    if (analyzeByStoreBtn) {
        analyzeByStoreBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで店舗別分析
                const storeAnalysis = classifySalesDataByStore ? 
                    classifySalesDataByStore(salesResponse.data) : 
                    salesResponse.data;

                const tbody = container.querySelector('#storeAnalysisTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(storeAnalysis).forEach(([storeId, data]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = storeId;
                        row.insertCell(1).textContent = data.totalQuantity || data.quantity || 0;
                        row.insertCell(2).textContent = data.totalAmount || data.amount || 0;
                        row.insertCell(3).textContent = data.averagePrice || (data.totalAmount / data.totalQuantity).toFixed(2) || 0;
                    });
                }
                window.aivicNotify.success('店舗別分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('店舗別分析に失敗しました: ' + error.message);
            }
        });
    }

    // 天気データ収集ボタン
    const collectWeatherBtn = container.querySelector('#collectWeatherBtn');
    if (collectWeatherBtn) {
        collectWeatherBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから天気データを取得
                const weatherResponse = await window.aivicApi.list('weather', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで処理
                const weatherData = collectWeatherData ? 
                    collectWeatherData(weatherResponse.data, startDate, endDate) : 
                    weatherResponse.data;

                const tbody = container.querySelector('#weatherDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    weatherData.forEach(item => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = item.date;
                        row.insertCell(1).textContent = item.weather || item.condition;
                        row.insertCell(2).textContent = item.temperature;
                        row.insertCell(3).textContent = item.humidity;
                    });
                }
                window.aivicNotify.success('天気データを収集しました');
            } catch (error) {
                window.aivicNotify.error('天気データの収集に失敗しました: ' + error.message);
            }
        });
    }

    // イベントデータ収集ボタン
    const collectEventBtn = container.querySelector('#collectEventBtn');
    if (collectEventBtn) {
        collectEventBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIからイベントデータを取得
                const eventResponse = await window.aivicApi.list('events', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで処理
                const eventData = collectEventData ? 
                    collectEventData(eventResponse.data, startDate, endDate) : 
                    eventResponse.data;

                const tbody = container.querySelector('#eventDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    eventData.forEach(item => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = item.date;
                        row.insertCell(1).textContent = item.eventName || item.name;
                        row.insertCell(2).textContent = item.eventType || item.type;
                        row.insertCell(3).textContent = item.impact || item.expectedImpact;
                    });
                }
                window.aivicNotify.success('イベントデータを収集しました');
            } catch (error) {
                window.aivicNotify.error('イベントデータの収集に失敗しました: ' + error.message);
            }
        });
    }

    // 相関分析ボタン
    const analyzeCorrelationBtn = container.querySelector('#analyzeCorrelationBtn');
    if (analyzeCorrelationBtn) {
        analyzeCorrelationBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // 各種データを取得
                const [salesResponse, weatherResponse, eventResponse] = await Promise.all([
                    window.aivicApi.list('sales', { startDate, endDate }),
                    window.aivicApi.list('weather', { startDate, endDate }),
                    window.aivicApi.list('events', { startDate, endDate })
                ]);

                // 業務ロジックで相関分析
                const weatherCorrelation = analyzeCorrelationSalesWeather ? 
                    analyzeCorrelationSalesWeather(salesResponse.data, weatherResponse.data) : {};
                const eventCorrelation = analyzeCorrelationSalesEvent ? 
                    analyzeCorrelationSalesEvent(salesResponse.data, eventResponse.data) : {};

                // 結果を表示
                const resultDiv = container.querySelector('#correlationResult');
                if (resultDiv) {
                    resultDiv.innerHTML = `
                        <h4>相関分析結果</h4>
                        <p>天気との相関係数: ${weatherCorrelation.coefficient || 'N/A'}</p>
                        <p>イベントとの相関係数: ${eventCorrelation.coefficient || 'N/A'}</p>
                        <p>分析期間: ${startDate} ～ ${endDate}</p>
                    `;
                }

                window.aivicNotify.success('相関分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('相関分析に失敗しました: ' + error.message);
            }
        });
    }

    // 履歴比較ボタン
    const compareHistoryBtn = container.querySelector('#compareHistoryBtn');
    if (compareHistoryBtn) {
        compareHistoryBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // 現在の期間と過去の期間のデータを取得
                const currentResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 1年前の同期間のデータを取得
                const lastYearStart = new Date(startDate);
                lastYearStart.setFullYear(lastYearStart.getFullYear() - 1);
                const lastYearEnd = new Date(endDate);
                lastYearEnd.setFullYear(lastYearEnd.getFullYear() - 1);

                const historicalResponse = await window.aivicApi.list('sales', {
                    startDate: lastYearStart.toISOString().split('T')[0],
                    endDate: lastYearEnd.toISOString().split('T')[0]
                });

                // 業務ロジックで比較
                const comparison = compareWithHistoricalData ? 
                    compareWithHistoricalData(currentResponse.data, historicalResponse.data) : {};

                // 結果を表示
                const resultDiv = container.querySelector('#comparisonResult');
                if (resultDiv) {
                    resultDiv.innerHTML = `
                        <h4>履歴比較結果</h4>
                        <p>売上成長率: ${comparison.growthRate || 'N/A'}%</p>
                        <p>数量変化率: ${comparison.quantityChange || 'N/A'}%</p>
                        <p>比較期間: ${startDate} ～ ${endDate} vs 前年同期</p>
                    `;
                }

                window.aivicNotify.success('履歴比較を完了しました');
            } catch (error) {
                window.aivicNotify.error('履歴比較に失敗しました: ' + error.message);
            }
        });
    }

    // 需要予測ボタン
    const predictDemandBtn = container.querySelector('#predictDemandBtn');
    if (predictDemandBtn) {
        predictDemandBtn.addEventListener('click', async () => {
            try {
                const productId = container.querySelector('#productId')?.value;
                const forecastDays = container.querySelector('#forecastDays')?.value || 30;

                if (!productId) {
                    window.aivicNotify.error('商品IDを入力してください');
                    return;
                }

                // 過去のデータを取得して予測
                const endDate = new Date().toISOString().split('T')[0];
                const startDate = new Date();
                startDate.setDate(startDate.getDate() - 90); // 過去90日分

                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate.toISOString().split('T')[0],
                    endDate: endDate,
                    productId: productId
                });

                // 簡易的な需要予測（移動平均）
                const salesData = salesResponse.data;
                const avgDemand = salesData.reduce((sum, item) => sum + (item.quantity || 0), 0) / salesData.length;
                const predictedDemand = Math.round(avgDemand * forecastDays);

                // 結果を表示
                const resultDiv = container.querySelector('#predictionResult');
                if (resultDiv) {
                    resultDiv.innerHTML = `
                        <h4>需要予測結果</h4>
                        <p>商品ID: ${productId}</p>
                        <p>予測期間: ${forecastDays}日間</p>
                        <p>予測需要量: ${predictedDemand}個</p>
                        <p>日平均予測: ${avgDemand.toFixed(2)}個/日</p>
                    `;
                }

                window.aivicNotify.success('需要予測を完了しました');
            } catch (error) {
                window.aivicNotify.error('需要予測に失敗しました: ' + error.message);
            }
        });
    }

    // 初期化時に今日の日付を設定
    const today = new Date().toISOString().split('T')[0];
    const startDateInput = container.querySelector('#startDate');
    const endDateInput = container.querySelector('#endDate');

    if (startDateInput && !startDateInput.value) {
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        startDateInput.value = thirtyDaysAgo.toISOString().split('T')[0];
    }

    if (endDateInput && !endDateInput.value) {
        endDateInput.value = today;
    }
}
